<?php
require_once __DIR__.'/../includes/bootstrap.php'; require_admin();
if(!super_admin()){http_response_code(403);exit('Not authorised. Only the main administrator can manage administrator accounts.');}
$title='Admin & Staff Accounts';$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  check_csrf(); $action=(string)($_POST['action']??'');
  try{
    if($action==='add'){
      $u=trim((string)($_POST['username']??''));$email=strtolower(trim((string)($_POST['email']??'')));$phone=trim((string)($_POST['phone']??''));$p=(string)($_POST['password']??'');$role=(string)($_POST['role']??'Staff');
      if($u===''||strlen($p)<8)$err='Username and a password of at least 8 characters are required.';
      elseif($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$err='Enter a valid recovery email.';
      elseif(!in_array($role,['Admin','Staff'],true))$err='Invalid role.';
      else{$s=$pdo->prepare('SELECT user_id FROM users WHERE LOWER(username)=LOWER(?)');$s->execute([$u]);if($s->fetch())$err='That management username already exists.';else{$s=$pdo->prepare('INSERT INTO users(username,password_hash,role,is_super_admin,email,phone) VALUES(?,?,?,?,?,?)');$s->execute([$u,password_hash($p,PASSWORD_DEFAULT),$role,0,$email?:null,$phone?:null]);audit_log('CREATE MANAGEMENT ACCOUNT',$u.' / '.$role);$msg='Management account added. Recovery email is ready for Forgot Password.';}}
    }elseif($action==='save_profile'){
      $id=(int)$_POST['user_id'];$email=strtolower(trim((string)$_POST['email']??''));$phone=trim((string)$_POST['phone']??'');
      if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$err='Enter a valid recovery email.';else{$pdo->prepare('UPDATE users SET email=?,phone=?,updated_at=NOW() WHERE user_id=?')->execute([$email?:null,$phone?:null,$id]);audit_log('UPDATE MANAGEMENT PROFILE','user_id='.$id);$msg='Management recovery details saved.';}
    }elseif($action==='delete'){
      $id=(int)$_POST['user_id'];if($id===(int)$_SESSION['admin_id'])$err='You cannot remove the current administrator.';else{$pdo->prepare('UPDATE transactions SET user_id=NULL WHERE user_id=?')->execute([$id]);$pdo->prepare('DELETE FROM users WHERE user_id=? AND is_super_admin=0')->execute([$id]);audit_log('REMOVE MANAGEMENT ACCOUNT','user_id='.$id);$msg='Account removed.';}
    }
  }catch(Throwable $e){$err='The management account action could not be completed.';}
}
$rows=$pdo->query('SELECT user_id,username,email,phone,role,is_super_admin,created_at,updated_at FROM users ORDER BY is_super_admin DESC,user_id ASC')->fetchAll();
require __DIR__.'/../includes/header.php';
?><div class="admin-layout"><aside class="admin-side"><strong>Management</strong><a href="/admin/dashboard.php">Dashboard</a><a href="/admin/stock.php">Stock control</a><a href="/admin/orders.php">Orders</a><a class="active" href="/admin/users.php">Admin & Staff</a><a href="/admin/settings.php">Settings</a><a href="/admin/audit.php">Audit log</a><a href="/admin/system.php">System health</a><a href="/">View store</a></aside><section class="admin-main"><div class="section-head"><div><span class="eyebrow">SECURE MANAGEMENT</span><h1>Admin & Staff accounts</h1><p>Every management account can recover its password through its registered email without an OTP. The main administrator controls account creation.</p></div></div><?php if($msg):?><div class="flash success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="errors"><?=e($err)?></div><?php endif;?><div class="panel"><h2>Add Admin or Staff</h2><form method="post" class="form management-add-grid"><?=csrf_field()?><input type="hidden" name="action" value="add"><label>Username<input name="username" required></label><label>Recovery email<input type="email" name="email" placeholder="required for password recovery"></label><label>Phone<input name="phone"></label><label>Temporary password<input type="password" name="password" minlength="8" required></label><label>Role<select name="role"><option>Staff</option><option>Admin</option></select></label><button class="btn primary">Create account</button></form></div><div class="table-wrap"><table><thead><tr><th>Username</th><th>Role</th><th>Recovery email</th><th>Phone</th><th>Security</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['username'])?></strong><?php if((int)$r['is_super_admin']):?><small>Main administrator</small><?php endif;?></td><td><?=e($r['role'])?></td><td><form method="post" class="row-form"><?=csrf_field()?><input type="hidden" name="action" value="save_profile"><input type="hidden" name="user_id" value="<?=$r['user_id']?>"><input type="email" name="email" value="<?=e($r['email']??'')?>" placeholder="Recovery email"><input type="hidden" name="phone" value="<?=e($r['phone']??'')?>"><button class="btn small">Save</button></form></td><td><form method="post" class="row-form"><?=csrf_field()?><input type="hidden" name="action" value="save_profile"><input type="hidden" name="user_id" value="<?=$r['user_id']?>"><input type="hidden" name="email" value="<?=e($r['email']??'')?>"><input name="phone" value="<?=e($r['phone']??'')?>" placeholder="Phone"><button class="btn small">Save</button></form></td><td><span class="status-pill status-delivered"><?=empty($r['email'])?'Recovery email missing':'Recovery ready'?></span></td><td><?php if(!(int)$r['is_super_admin']):?><form method="post" onsubmit="return confirm('Remove this account?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="user_id" value="<?=$r['user_id']?>"><button class="link-danger">Remove</button></form><?php else:?><span class="muted">Protected</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><div class="admin-help-strip"><strong>Forgot Password</strong><span>Management users should use <a href="/auth/admin-forgot-password.php">Management Forgot Password</a>. The secure email link expires automatically.</span></div></section></div><?php require __DIR__.'/../includes/footer.php';?>
